/**
 * Renders the deterministic investigation plan (`investigation-planner.ts`)
 * generated by `start_investigation` — an ordered checklist with real
 * pending/done/skipped status and the real count, never a progress bar.
 */

import type { InvestigationPlan, PlanStep } from "@apty/browser-runtime";
import { useTranslation } from "@apty/ui/i18n/context";
import type { TranslationKey } from "@apty/ui/i18n/types";
import { cn } from "@apty/ui/lib/utils";
import { CheckIcon, MinusIcon } from "lucide-react";

const STATE_WORD: Record<PlanStep["status"], TranslationKey> = {
  pending: "investigation.plan.state.pending",
  done: "investigation.plan.state.done",
  skipped: "investigation.plan.state.skipped",
};

const CATEGORY_LABEL: Record<string, TranslationKey> = {
  generic: "investigation.plan.category.generic",
  "retrieve-resource-data": "investigation.plan.category.retrieveResourceData",
  "tooltip-not-showing": "investigation.plan.category.tooltipNotShowing",
  "studio-cannot-select": "investigation.plan.category.studioCannotSelect",
  "studio-vs-production": "investigation.plan.category.studioVsProduction",
  "workflow-not-triggering":
    "investigation.plan.category.workflowNotTriggering",
  "widget-not-loading": "investigation.plan.category.widgetNotLoading",
};

/** Done and total steps of a plan, as the summary bar and the checklist both show them. */
export function planCounts(plan: InvestigationPlan): {
  done: number;
  total: number;
} {
  return {
    done: plan.steps.filter((s) => s.status === "done").length,
    total: plan.steps.length,
  };
}

function StepMarker({ step, index }: { step: PlanStep; index: number }) {
  const base =
    "flex size-5 shrink-0 items-center justify-center rounded-full text-xs font-medium";
  if (step.status === "done") {
    return (
      <span
        aria-hidden="true"
        className={cn(base, "bg-success text-success-foreground")}
      >
        <CheckIcon className="size-3" />
      </span>
    );
  }
  if (step.status === "skipped") {
    return (
      <span
        aria-hidden="true"
        className={cn(base, "border border-border text-subtle-foreground")}
      >
        <MinusIcon className="size-3" />
      </span>
    );
  }
  return (
    <span
      aria-hidden="true"
      className={cn(base, "border border-input text-muted-foreground")}
    >
      {index + 1}
    </span>
  );
}

export function PlanChecklist({
  plan,
}: {
  plan: InvestigationPlan | undefined;
}) {
  const { t } = useTranslation();
  if (!plan) {
    return (
      <p className="py-2 text-sm text-muted-foreground">
        {t("investigation.plan.none")}
      </p>
    );
  }

  const { done, total } = planCounts(plan);
  const category = CATEGORY_LABEL[plan.category];

  return (
    <div className="space-y-2">
      <p className="flex flex-wrap justify-between gap-x-3 text-xs text-muted-foreground">
        <span>{t("investigation.plan.stepsDone", { done, total })}</span>
        <span>{category ? t(category) : plan.category}</span>
      </p>
      <ol className="space-y-2">
        {plan.steps.map((step, index) => (
          <li key={step.id} className="flex items-start gap-3 text-sm">
            <StepMarker step={step} index={index} />
            <span
              className={cn(
                "min-w-0 flex-1",
                step.status === "pending"
                  ? "text-foreground"
                  : step.status === "done"
                    ? "text-muted-foreground"
                    : "text-subtle-foreground",
              )}
            >
              {step.description}
              <span className="sr-only">{`, ${t(STATE_WORD[step.status])}`}</span>
            </span>
          </li>
        ))}
      </ol>
    </div>
  );
}
